package com.example.audioinsight.ui;
import android.os.Bundle;
import android.text.InputType;
import android.widget.*;
import com.example.audioinsight.data.*;
import org.json.JSONObject;
public class SettingsActivity extends UiActivity {
    @Override public void onCreate(Bundle s){super.onCreate(s);page("设置","USB 连接电脑，整理手机中的声音",false,3);LinearLayout c=card();c.addView(text("服务连接",19,INK));TextView help=text("用 USB 连接手机与电脑，并在电脑上运行“手机连接”脚本。连接成功后，真机服务地址使用下方的 USB 地址。",14,MUTED);help.setPadding(0,dp(12),0,dp(18));c.addView(help);EditText address=input("http://127.0.0.1:8000");address.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_URI);address.setText(AppSettings.baseUrl(this));c.addView(address);pair(c,"填入 USB 地址",v->address.setText("http://127.0.0.1:8000"),"填入模拟器地址",v->address.setText("http://10.0.2.2:8000"));TextView status=text("填入地址后请点击保存。",13,MUTED);status.setPadding(0,dp(12),0,0);c.addView(status);pair(c,"保存地址",v->{try{String value=ApiClient.normalizeBaseUrl(address.getText().toString().trim());AppSettings.setBaseUrl(this,value);address.setText(value);status.setText("已保存。新任务将使用此地址。");toast("服务地址已保存");}catch(Exception e){error("请填写完整的 http:// 或 https:// 服务地址。");}},"检测连接",v->{v.setEnabled(false);status.setText("正在检测，请稍候…");repo.checkConnection(address.getText().toString().trim(),new Callback<JSONObject>(){public void onSuccess(JSONObject result){v.setEnabled(true);status.setText("●  服务连接正常，可以开始整理");status.setTextColor(CYAN);}public void onError(String m){v.setEnabled(true);status.setText("连接失败："+m);status.setTextColor(0xffffb8ad);}});});label("USB 连接步骤");LinearLayout tips=card();tips.addView(text("真机连接电脑",16,INK));tips.addView(text("1. 在手机开启开发者选项与 USB 调试。\n2. 用数据线连接电脑，在手机上允许此电脑调试。\n3. 在电脑运行“手机连接”脚本，保持服务运行。\n4. 填入 USB 地址并保存，再点击“检测连接”。\n\n每次重新插拔数据线或重启电脑后，可重新运行连接脚本。使用模拟器时，请改填模拟器地址。",14,MUTED));LinearLayout local=card();local.addView(text("记录与隐私",16,INK));local.addView(text("录音、文件和历史记录保存在本机。提交后，音视频会发送至上方设置的电脑服务进行识别与整理。请在录制他人声音前征得同意。",14,MUTED));addButton(body,"关于音频智记",false,v->open(AboutActivity.class));}
}
